input.script:
export const meta = {
  name: 'pr-stall-supersede-audit',
  description: 'Quantify how often engaged contributor PRs stalled/were superseded in gastownhall/beads, and which open PRs are in that state now',
  phases: [
    { title: 'Sweep', detail: 'history of superseded closures, doomed open PRs, waiting queue' },
    { title: 'Verify', detail: 'confirm doomed-open candidates against main' },
  ],
}

const spent0 = budget.spent()
const TARGET = 200_000

const RULES = `You are doing read-only recon on the GitHub repo gastownhall/beads using the gh CLI (already authenticated). Local checkout of the repo is at bd-main/ (remote upstream = gastownhall/beads). "Maintainer" = comment/review authorAssociation MEMBER, OWNER, or COLLABORATOR (maphew is the primary maintainer; posts signed "on behalf of maphew" count as maintainer). Ignore bot accounts (github-actions, codecov, etc). Do NOT run any bd command, do NOT write files outside the scratchpad, do NOT post anything to GitHub. Be rigorous about dates. If you cap or sample, say exactly what you dropped.`

phase('Sweep')

const HISTORY_SCHEMA = {
  type: 'object', required: ['cases', 'method', 'totals'],
  properties: {
    cases: { type: 'array', items: { type: 'object', required: ['pr', 'author', 'pattern', 'evidence'], properties: {
      pr: { type: 'number' }, author: { type: 'string' },
      openedAt: { type: 'string' }, closedAt: { type: 'string' },
      ageDaysAtClose: { type: 'number' },
      pattern: { type: 'string', enum: ['engaged-then-superseded', 'author-replied-then-stalled-then-closed', 'never-answered-then-closed-redundant', 'other-redundant-close'] },
      supersededBy: { type: 'string' }, evidence: { type: 'string' } } } },
    totals: { type: 'object' },
    method: { type: 'string' }, dropped: { type: 'string' },
  },
}

const DOOMED_SCHEMA = {
  type: 'object', required: ['candidates', 'method'],
  properties: {
    candidates: { type: 'array', items: { type: 'object', required: ['pr', 'author', 'rationale'], properties: {
      pr: { type: 'number' }, author: { type: 'string' }, openedAt: { type: 'string' },
      overlapsWith: { type: 'string' }, rationale: { type: 'string' },
      maintainerEverEngaged: { type: 'boolean' } } } },
    method: { type: 'string' }, dropped: { type: 'string' },
  },
}

const WAIT_SCHEMA = {
  type: 'object', required: ['neverAnswered', 'waitingAfterReply'],
  properties: {
    neverAnswered: { type: 'array', items: { type: 'object', required: ['pr', 'author', 'ageDays'], properties: { pr: { type: 'number' }, author: { type: 'string' }, ageDays: { type: 'number' }, title: { type: 'string' } } } },
    waitingAfterReply: { type: 'array', items: { type: 'object', required: ['pr', 'author', 'daysWaiting'], properties: { pr: { type: 'number' }, author: { type: 'string' }, daysWaiting: { type: 'number' }, lastAuthorActivity: { type: 'string' }, title: { type: 'string' } } } },
    counts: { type: 'object' }, notes: { type: 'string' },
  },
}

const [history, doomed, waiting] = await parallel([
  () => agent(`${RULES}

TASK: Find every CLOSED-WITHOUT-MERGE pull request in gastownhall/beads that was made redundant by other work (superseded, duplicate, already-landed, absorbed), and classify how the contributor was treated before closure. Today is 2026-07-26.

Method suggestion (adapt as needed):
1. gh search prs --repo gastownhall/beads --state closed "superseded" (and separately: "duplicate", "already landed", "absorbed", "retiring", "already fixed", "already implemented") -- also try: gh pr list --repo gastownhall/beads --state closed --limit 400 --json number,title,author,createdAt,closedAt,mergedAt then filter mergedAt==null and probe the ones from outside contributors.
2. Also grep the LOCAL coordination-repo directory reports/ (in the current working directory, NOT bd-main) for retirement/supersede decisions: grep -ril "supersed\\|absorbed\\|retire" reports/ | head -30 — these documents record why PRs were closed and often list PR numbers.
3. For each candidate closed PR, fetch its comments/reviews (gh pr view N --repo gastownhall/beads --json author,createdAt,closedAt,comments,reviews) and classify into exactly one pattern:
   - engaged-then-superseded: a maintainer engaged (review/comment), the author responded/updated, and the PR was later closed because equivalent work landed elsewhere.
   - author-replied-then-stalled-then-closed: author answered a maintainer and then waited >14 days with no maintainer reply before the close.  (A PR can be this AND superseded; prefer engaged-then-superseded if both.)
   - never-answered-then-closed-redundant: no maintainer interaction at all before a redundant-close.
   - other-redundant-close: redundant close that doesn't fit above (e.g. author self-closed, or close came quickly with explanation).
4. Only count PRs from outside contributors (authorAssociation NONE/CONTRIBUTOR/FIRST_TIME_CONTRIBUTOR). Exclude maphew's own PRs and bot PRs.
Cap detailed probing at ~50 PRs, prioritizing ones with maintainer engagement; report in "dropped" what you didn't probe. In evidence give a one-line timeline (opened → key events with dates → closed, superseded-by ref).
Return totals: {byPattern: {...}, probed: N, candidatePool: N}.`,
    { label: 'history:superseded-closures', phase: 'Sweep', schema: HISTORY_SCHEMA }),

  () => agent(`${RULES}

TASK: Find OPEN pull requests in gastownhall/beads that are already doomed — their change (or its core) has ALREADY landed on main via a different PR or commit, but the PR is still open and the author may not know. Today is 2026-07-26. This is the pattern that just burned PR #4376 (open 44 days, fix landed independently via #4939). Exclude #4376 itself from candidates (already known).

Method suggestion:
1. gh pr list --repo gastownhall/beads --state open --limit 200 --json number,title,author,createdAt,files,labels,isDraft — keep non-draft PRs from outside contributors (exclude maphew, bots).
2. gh pr list --repo gastownhall/beads --state merged --limit 250 --json number,title,mergedAt,files — merged in the last ~8 weeks.
3. Cross-match: for each open PR, look for merged PRs touching the same files with similar intent (title keywords, same bug area). Where suspicious, read the open PR body and the merged PR body to judge whether the open PR is redundant.
4. Also check: for open PRs that claim to fix a specific bug, git -C bd-main log --oneline --since="2026-06-01" -- <file> can show whether main already changed that code.
Return every candidate with a concrete rationale naming the overlapping merged PR/commit. Flag maintainerEverEngaged (any maintainer comment/review on the open PR). Prefer precision over recall for strong claims, but list weak suspicions too with rationale marked "weak:". Cap deep reads at ~30 open PRs; note drops.`,
    { label: 'doomed:open-vs-main', phase: 'Sweep', schema: DOOMED_SCHEMA }),

  () => agent(`${RULES}

TASK: Recompute the "ball in our court" queue for gastownhall/beads as of NOW (2026-07-26/27). For every OPEN, non-draft PR from an outside contributor (exclude maphew, bots):
1. Pull the full comment+review timeline (gh pr view N --json comments,reviews,author,createdAt,title -- batch via gh pr list --state open --limit 200 --json number,author,isDraft,createdAt,title first).
2. Determine the LAST SUBSTANTIVE actor: maintainer (MEMBER/OWNER/COLLABORATOR or signed "on behalf of maphew") vs contributor. New commits by the author after a maintainer review also count as contributor activity if you can see them cheaply (updatedAt vs last maintainer comment is an acceptable proxy — say so in notes if you used the proxy).
3. Output two lists: neverAnswered (zero maintainer comments AND zero maintainer reviews ever, with age in days) and waitingAfterReply (contributor acted after the last maintainer touch and has been waiting, with daysWaiting since the contributor's last activity). Sort each by days descending.
counts should include: totalOpenExternal, neverAnswered, waitingAfterReply, ballInTheirCourt.
This refreshes a 2026-07-25 measurement that found 5 never-answered and 20 waiting-after-reply; expect numbers near that but recompute honestly — do not anchor on it. Process ALL open external PRs, not a sample; if you must cap, cap by processing oldest-first and say exactly which you skipped.`,
    { label: 'waiting:ball-in-our-court', phase: 'Sweep', schema: WAIT_SCHEMA }),
])

log(`sweep done; budget delta ${Math.round((budget.spent() - spent0) / 1000)}k of ${TARGET / 1000}k target`)

phase('Verify')

const VERIFY_SCHEMA = {
  type: 'object', required: ['pr', 'verdict', 'evidence'],
  properties: { pr: { type: 'number' }, verdict: { type: 'string', enum: ['redundant', 'partially-redundant', 'not-redundant', 'unclear'] }, evidence: { type: 'string' } },
}

let verified = []
const strong = (doomed?.candidates || []).filter(c => c && !String(c.rationale || '').startsWith('weak:')).slice(0, 8)
if (doomed && (doomed.candidates || []).length > strong.length) log(`verifying ${strong.length} strong candidates of ${(doomed.candidates || []).length} total (weak/-overflow skipped, listed in report)`)
if (strong.length && budget.spent() - spent0 < TARGET) {
  verified = (await parallel(strong.map(c => () =>
    agent(`${RULES}

An earlier sweep claims open PR gastownhall/beads#${c.pr} (by ${c.author}) is already redundant because: ${c.rationale} (overlaps with: ${c.overlapsWith || 'unspecified'}).
Adversarially verify this. Read the open PR's actual diff (gh pr diff ${c.pr} --repo gastownhall/beads | head -300), read the allegedly overlapping merged work (gh pr diff or git -C bd-main show), and judge: does main already contain the substance of this open PR? Distinguish "same files, different behavior" from genuine redundancy. Default to 'unclear' if you cannot confirm.`,
      { label: `verify:#${c.pr}`, phase: 'Verify', schema: VERIFY_SCHEMA })
  ))).filter(Boolean)
} else if (strong.length) {
  log(`SKIPPED verification of ${strong.length} candidates: budget target reached — treat candidates as unverified`)
}

return {
  history: history || 'AGENT FAILED',
  doomed: doomed || 'AGENT FAILED',
  waiting: waiting || 'AGENT FAILED',
  verified,
  budgetUsed: budget.spent() - spent0,
}
